package com.example.examplemod.economy.company;

import com.example.examplemod.cargo.center.CargoCommerceBook;
import com.example.examplemod.cargo.center.OwnerRef;
import net.minecraft.nbt.*;
import java.math.BigInteger;
import java.util.*;
import java.util.function.ToLongFunction;

/** Company obligations and their financial effects are saved with the actual accounts. */
public final class CompanyBook {
    public static final long DAY = 86_400_000L;
    public static final int INITIAL_SHARES = 10_000;
    public enum Permission { VIEW, PERSONNEL, ASSETS, TRADE, DISPATCH, SPEND, CAPITAL }
    public enum Role {
        DIRECTOR, ACCOUNTANT, MANAGER, LOGISTICIAN, WORKER;
        public boolean permits(Permission p) {
            return switch (this) {
                case DIRECTOR -> true;
                case ACCOUNTANT -> p == Permission.VIEW || p == Permission.SPEND;
                case MANAGER -> p == Permission.VIEW || p == Permission.PERSONNEL || p == Permission.ASSETS || p == Permission.TRADE;
                case LOGISTICIAN -> p == Permission.VIEW || p == Permission.ASSETS || p == Permission.TRADE || p == Permission.DISPATCH;
                case WORKER -> p == Permission.VIEW;
            };
        }
    }
    public enum AssetKind { TRAIN, POINT, WAREHOUSE, PRODUCTION, STORE, ROAD }
    public enum ContractKind { SUPPLY, TRANSPORT, EMPLOYMENT, INFRASTRUCTURE }
    public enum ContractState { OFFERED, ACCEPTED, COMPLETED, REJECTED, CANCELLED }
    public enum Decision { DIRECTOR, CITY, CHARTER, ISSUE_SHARES, DIVIDEND, ARCHIVE }
    public record Employee(UUID player, Role role, long salary, long started, long accruedUntil,
                           long ended, long remainder, long arrears, long firstUnpaid) {
        public boolean active() { return ended == 0; }
    }
    public record Invite(UUID id, UUID company, UUID player, Role role, long salary, long expires, boolean amendment, UUID appointment) {
        public Invite(UUID id,UUID company,UUID player,Role role,long salary,long expires){this(id,company,player,role,salary,expires,false,null);}
        public Invite(UUID id,UUID company,UUID player,Role role,long salary,long expires,boolean amendment){this(id,company,player,role,salary,expires,amendment,null);}
    }
    public record Asset(UUID id, AssetKind kind, UUID reference, String name) {}
    public record Contract(UUID id, UUID company, ContractKind kind, OwnerRef counterparty, UUID reference,
                           long amount, int quantity, String terms, ContractState state, long created, long expires) {}
    public record ShareOffer(UUID id, UUID company, UUID seller, UUID buyer, int units, long price,
                             long expires, boolean closed, int capital, String charter, UUID city, long taxVersion) {}
    public record TaxPolicy(int basisPoints, long version) {}
    public record Revenue(UUID receipt, UUID company, UUID city, long gross, long tax, int rate, long policy, long time) {}
    public record Vote(UUID id, UUID company, Decision decision, UUID target, long amount, String text,
                       Map<UUID,Integer> electorate, Map<UUID,Boolean> ballots, long expires, String state) {
        public Vote { electorate = Map.copyOf(electorate); ballots = Map.copyOf(ballots); }
        public long yes() { return ballots.entrySet().stream().filter(Map.Entry::getValue).mapToLong(e -> electorate.getOrDefault(e.getKey(),0)).sum(); }
        public long total() { return electorate.values().stream().mapToLong(Integer::longValue).sum(); }
    }
    public static final class Company {
        private final UUID id, founder;
        private String name, charter = "";
        private UUID city;
        private UUID pendingDirector;
        private boolean archived;
        private long revision, revenue, taxPaid, taxRemainder, salaryPaid;
        private final Map<UUID,Employee> employees = new LinkedHashMap<>();
        private final Map<UUID,Integer> shares = new LinkedHashMap<>();
        private final Map<UUID,Asset> assets = new LinkedHashMap<>();
        private Company(UUID id, UUID founder, String name, UUID city) { this.id=id; this.founder=founder; this.name=name; this.city=city; }
        public UUID id(){return id;} public UUID founder(){return founder;} public String name(){return name;}
        public UUID city(){return city;} public boolean archived(){return archived;} public long revision(){return revision;}
        public String charter(){return charter;} public long revenue(){return revenue;} public long taxPaid(){return taxPaid;}
        public long salaryPaid(){return salaryPaid;} public List<Employee> employees(){return List.copyOf(employees.values());}
        public Map<UUID,Integer> shares(){return Map.copyOf(shares);} public List<Asset> assets(){return List.copyOf(assets.values());}
        public long salaryDebt(){long debt=0; for(var e:employees.values())debt=Math.addExact(debt,e.arrears());return debt;}
        public int totalShares(){return Math.toIntExact(shares.values().stream().mapToLong(Integer::longValue).sum());}
    }
    private final CargoCommerceBook.Accounts accounts;
    private ToLongFunction<OwnerRef> externalDebt = owner -> 0;
    private final Map<UUID,Company> companies = new LinkedHashMap<>();
    private final Map<UUID,Invite> invites = new LinkedHashMap<>();
    private final Map<UUID,Contract> contracts = new LinkedHashMap<>();
    private final Map<UUID,ShareOffer> shareOffers = new LinkedHashMap<>();
    private final Map<UUID,Vote> votes = new LinkedHashMap<>();
    private final Map<UUID,TaxPolicy> taxes = new LinkedHashMap<>();
    private final Map<UUID,Revenue> receipts = new LinkedHashMap<>();
    private final LinkedHashMap<UUID,String> commands = new LinkedHashMap<>();
    public CompanyBook(CargoCommerceBook.Accounts accounts){this.accounts=Objects.requireNonNull(accounts);}
    public void externalDebt(ToLongFunction<OwnerRef> value){externalDebt=Objects.requireNonNull(value);}
    public List<Company> all(){return List.copyOf(companies.values());}
    public Optional<Company> find(UUID id){return Optional.ofNullable(companies.get(id));}
    public List<Invite> invites(){return List.copyOf(invites.values());}
    public List<Contract> contracts(){return List.copyOf(contracts.values());}
    public List<ShareOffer> shareOffers(){return List.copyOf(shareOffers.values());}
    public List<Vote> votes(){return List.copyOf(votes.values());}
    public List<Revenue> receipts(){return List.copyOf(receipts.values());}
    public static OwnerRef owner(UUID id){return new OwnerRef(OwnerRef.Kind.COMPANY,id);}
    private Company company(UUID id){var c=companies.get(id);if(c==null||c.archived)throw new IllegalArgumentException("company_unavailable");return c;}
    public boolean available(UUID id){return companies.containsKey(id)&&!companies.get(id).archived;}
    public boolean permits(UUID id,UUID actor,Permission permission){var c=companies.get(id);if(c==null||c.archived)return false;var e=c.employees.get(actor);return e!=null&&e.active()&&e.role().permits(permission);}
    public boolean shareholder(UUID id,UUID actor){var c=companies.get(id);return c!=null&&!c.archived&&c.shares.getOrDefault(actor,0)>0;}
    public boolean visible(UUID id,UUID actor){return permits(id,actor,Permission.VIEW)||shareholder(id,actor);}
    private void require(UUID id,UUID actor,Permission p){if(!permits(id,actor,p))throw new IllegalArgumentException("company_permission");}
    private void changed(Company c){c.revision++;accounts.dirty();}
    private void money(long n,boolean zero){if(n<(zero?0:1)||n>accounts.maximum())throw new IllegalArgumentException("company_amount");}
    private static String text(String value,int max){if(value==null||value.isBlank()||value.length()>max)throw new IllegalArgumentException("company_text");return value.trim();}
    public Company create(UUID id,UUID founder,String name,UUID city,long now){
        text(name,64);Objects.requireNonNull(city);if(companies.containsKey(id))throw new IllegalArgumentException("company_exists");
        if(companies.values().stream().filter(c->!c.archived).count()>=2048||companies.values().stream().anyMatch(c->!c.archived&&c.name.equalsIgnoreCase(name.trim())))throw new IllegalArgumentException("company_limit");
        var c=new Company(id,founder,name.trim(),city);c.employees.put(founder,new Employee(founder,Role.DIRECTOR,0,now,now,0,0,0,0));c.shares.put(founder,INITIAL_SHARES);companies.put(id,c);changed(c);return c;
    }
    public TaxPolicy tax(UUID city){return taxes.getOrDefault(city,new TaxPolicy(0,0));}
    /** Caller is the city authority, checked by CompanyCenter; individual directors cannot choose their tax. */
    public void tax(UUID city,int basisPoints){if(basisPoints<0||basisPoints>10_000)throw new IllegalArgumentException("company_tax");var old=tax(city);taxes.put(city,new TaxPolicy(basisPoints,Math.addExact(old.version(),1)));accounts.dirty();}
    public long taxAmount(UUID company,long gross){var c=company(company);if(gross<0)throw new IllegalArgumentException("company_amount");return BigInteger.valueOf(gross).multiply(BigInteger.valueOf(tax(c.city).basisPoints())).add(BigInteger.valueOf(c.taxRemainder)).divide(BigInteger.valueOf(10_000)).longValueExact();}
    public Map<OwnerRef,Long> revenueCredits(UUID company,long gross){var c=company(company);long tax=taxAmount(company,gross);Math.addExact(c.revenue,gross);Math.addExact(c.taxPaid,tax);var result=new LinkedHashMap<OwnerRef,Long>();if(gross-tax>0)result.put(owner(company),gross-tax);if(tax>0)result.merge(new OwnerRef(OwnerRef.Kind.CITY,c.city),tax,Math::addExact);return result;}
    public boolean canReceiveRevenue(UUID id,long gross){try{return revenueCredits(id,gross).entrySet().stream().allMatch(e->accounts.canCredit(e.getKey(),e.getValue()));}catch(RuntimeException invalid){return false;}}
    /** Stable source UUID + actual credits + tax remainder are committed in the same financial save. */
    public void revenue(UUID receipt,UUID id,long gross,long now){
        var old=receipts.get(receipt);if(old!=null){if(!old.company().equals(id)||old.gross()!=gross)throw new IllegalArgumentException("company_receipt_conflict");return;}
        var c=company(id);if(gross<0||!canReceiveRevenue(id,gross))throw new IllegalArgumentException("company_credit");var p=tax(c.city);long tax=taxAmount(id,gross);
        long nextRevenue=Math.addExact(c.revenue,gross),nextTax=Math.addExact(c.taxPaid,tax);
        long remainder=BigInteger.valueOf(gross).multiply(BigInteger.valueOf(p.basisPoints())).add(BigInteger.valueOf(c.taxRemainder)).remainder(BigInteger.valueOf(10_000)).longValueExact();
        for(var e:revenueCredits(id,gross).entrySet())accounts.credit(e.getKey(),e.getValue());
        c.revenue=nextRevenue;c.taxPaid=nextTax;c.taxRemainder=remainder;receipts.put(receipt,new Revenue(receipt,id,c.city,gross,tax,p.basisPoints(),p.version(),now));changed(c);
    }
    public void deposit(UUID id,UUID player,long amount){company(id);money(amount,false);transfer(OwnerRef.player(player),owner(id),amount);changed(company(id));}
    public long distributable(UUID id,long now){var c=company(id);accrue(c,now);long due=Math.addExact(c.salaryDebt(),Math.max(0,externalDebt.applyAsLong(owner(id))));return Math.max(0,accounts.balance(owner(id))-Math.min(accounts.balance(owner(id)),due));}
    public void withdraw(UUID id,UUID actor,long amount,long now){require(id,actor,Permission.SPEND);money(amount,false);if(amount>distributable(id,now))throw new IllegalArgumentException("company_obligations");transfer(owner(id),OwnerRef.player(actor),amount);changed(company(id));}
    private void transfer(OwnerRef from,OwnerRef to,long amount){if(amount==0)return;if(!accounts.canCredit(to,amount)||!accounts.debit(from,amount))throw new IllegalArgumentException("company_funds");accounts.credit(to,amount);accounts.dirty();}
    public Invite invite(UUID id,UUID actor,UUID target,Role role,long salary,long now){require(id,actor,Permission.PERSONNEL);money(salary,true);var c=company(id);if(role==Role.DIRECTOR)throw new IllegalArgumentException("company_vote_required");for(var p:Permission.values())if(role.permits(p)&&!permits(id,actor,p))throw new IllegalArgumentException("company_permission");if(c.employees.containsKey(target)&&c.employees.get(target).active())throw new IllegalArgumentException("company_employee_exists");if(invites.values().stream().anyMatch(i->i.company().equals(id)&&i.player().equals(target)&&i.expires()>now))throw new IllegalArgumentException("company_invite_exists");var i=new Invite(UUID.randomUUID(),id,target,role,salary,Math.addExact(now,7*DAY));invites.put(i.id(),i);changed(c);return i;}
    public Invite amendSalary(UUID id,UUID actor,UUID target,long salary,long now){require(id,actor,Permission.PERSONNEL);money(salary,true);var c=company(id);var employee=c.employees.get(target);if(employee==null||!employee.active())throw new IllegalArgumentException("company_employee_missing");if(invites.values().stream().anyMatch(i->i.company().equals(id)&&i.player().equals(target)&&i.expires()>now))throw new IllegalArgumentException("company_invite_exists");var invitation=new Invite(UUID.randomUUID(),id,target,employee.role(),salary,now+7*DAY,true);invites.put(invitation.id(),invitation);changed(c);return invitation;}
    public void acceptJob(UUID invitation,UUID actor,long now){var i=Optional.ofNullable(invites.get(invitation)).orElseThrow(()->new IllegalArgumentException("company_invite_missing"));if(!i.player().equals(actor)||i.expires()<now)throw new IllegalArgumentException("company_invite_expired");var c=company(i.company());if(i.appointment()!=null){var vote=votes.get(i.appointment());if(vote==null||vote.decision()!=Decision.DIRECTOR||!vote.state().equals("AWAITING_ACCEPTANCE")||!Objects.equals(c.pendingDirector,vote.id())||!actor.equals(vote.target()))throw new IllegalArgumentException("company_appointment_changed");appointDirector(c,actor,now,vote.id());votes.put(vote.id(),voteState(vote,"EXECUTED"));invites.remove(invitation);changed(c);return;}var old=c.employees.get(actor);if(i.amendment()?(old==null||!old.active()):(old!=null&&old.active()))throw new IllegalArgumentException("company_employee_exists");accrue(c,now);old=c.employees.get(actor);long debt=old==null?0:old.arrears(),remainder=old==null?0:old.remainder(),due=old==null?0:old.firstUnpaid(),until=old==null?now:Math.max(now,old.accruedUntil());var role=i.amendment()?old.role():i.role();c.employees.put(actor,new Employee(actor,role,i.salary(),i.amendment()?old.started():now,until,0,remainder,debt,due));for(var contract:List.copyOf(contracts.values()))if(contract.company().equals(c.id)&&contract.kind()==ContractKind.EMPLOYMENT&&contract.reference().equals(actor)&&contract.state()==ContractState.ACCEPTED)contracts.put(contract.id(),with(contract,ContractState.COMPLETED));invites.remove(invitation);contracts.put(i.id(),new Contract(i.id(),c.id,ContractKind.EMPLOYMENT,OwnerRef.player(actor),actor,i.salary(),0,"CR / real day",ContractState.ACCEPTED,now,Long.MAX_VALUE));changed(c);}
    public void declineJob(UUID invitation,UUID actor){var i=invites.get(invitation);if(i==null||!i.player().equals(actor))throw new IllegalArgumentException("company_permission");invites.remove(invitation);if(i.appointment()!=null){var c=company(i.company());if(Objects.equals(c.pendingDirector,i.appointment())){c.pendingDirector=null;var vote=votes.get(i.appointment());if(vote!=null)votes.put(vote.id(),voteState(vote,"DECLINED"));changed(c);}}accounts.dirty();}
    public void cancelInvitation(UUID invitation,UUID actor){var i=Optional.ofNullable(invites.get(invitation)).orElseThrow();require(i.company(),actor,Permission.PERSONNEL);if(i.appointment()!=null)throw new IllegalArgumentException("company_vote_required");invites.remove(invitation);changed(company(i.company()));}
    public void employeeRole(UUID id,UUID actor,UUID target,Role role){require(id,actor,Permission.PERSONNEL);var c=company(id);var e=Optional.ofNullable(c.employees.get(target)).orElseThrow();if(e.role()==Role.DIRECTOR||role==Role.DIRECTOR)throw new IllegalArgumentException("company_vote_required");for(var p:Permission.values())if(role.permits(p)&&!permits(id,actor,p))throw new IllegalArgumentException("company_permission");c.employees.put(target,new Employee(e.player(),role,e.salary(),e.started(),e.accruedUntil(),e.ended(),e.remainder(),e.arrears(),e.firstUnpaid()));changed(c);}
    public void endEmployment(UUID id,UUID actor,UUID target,long now){var c=company(id);if(!actor.equals(target))require(id,actor,Permission.PERSONNEL);var e=Optional.ofNullable(c.employees.get(target)).orElseThrow();if(e.role()==Role.DIRECTOR&&c.employees.values().stream().filter(x->x.active()&&x.role()==Role.DIRECTOR).count()==1)throw new IllegalArgumentException("company_last_director");accrue(c,now);e=c.employees.get(target);if(!e.active())return;c.employees.put(target,new Employee(e.player(),e.role(),e.salary(),e.started(),e.accruedUntil(),Math.max(now,e.accruedUntil()),e.remainder(),e.arrears(),e.firstUnpaid()));for(var contract:List.copyOf(contracts.values()))if(contract.company().equals(id)&&contract.kind()==ContractKind.EMPLOYMENT&&contract.reference().equals(target)&&contract.state()==ContractState.ACCEPTED)contracts.put(contract.id(),with(contract,ContractState.COMPLETED));changed(c);}
    private void accrue(Company c,long now){boolean changed=false;for(var e:List.copyOf(c.employees.values())){long until=Math.max(e.accruedUntil(),e.active()?now:Math.min(now,e.ended()));if(until<=e.accruedUntil())continue;long elapsed=until-e.accruedUntil();var numerator=BigInteger.valueOf(e.salary()).multiply(BigInteger.valueOf(elapsed)).add(BigInteger.valueOf(e.remainder()));var parts=numerator.divideAndRemainder(BigInteger.valueOf(DAY));long earned=parts[0].longValueExact(),debt=Math.addExact(e.arrears(),earned);c.employees.put(e.player(),new Employee(e.player(),e.role(),e.salary(),e.started(),until,e.ended(),parts[1].longValueExact(),debt,e.firstUnpaid()!=0?e.firstUnpaid():earned>0?e.accruedUntil():0));changed=true;}if(changed)changed(c);}
    public void payroll(long now){for(var c:companies.values()){if(c.archived)continue;accrue(c,now);var due=c.employees.values().stream().filter(e->e.arrears()>0).sorted(Comparator.comparingLong(Employee::firstUnpaid).thenComparing(e->e.player().toString())).toList();for(var e:due){long amount=Math.min(e.arrears(),accounts.balance(owner(c.id)));if(amount<=0)break;if(!accounts.canCredit(OwnerRef.player(e.player()),amount))continue;long paid=Math.addExact(c.salaryPaid,amount);transfer(owner(c.id),OwnerRef.player(e.player()),amount);c.salaryPaid=paid;c.employees.put(e.player(),new Employee(e.player(),e.role(),e.salary(),e.started(),e.accruedUntil(),e.ended(),e.remainder(),e.arrears()-amount,e.arrears()==amount?0:e.firstUnpaid()));changed(c);}}}
    public Asset asset(UUID id,UUID actor,AssetKind kind,UUID reference,String name){require(id,actor,Permission.ASSETS);var c=company(id);var asset=new Asset(stable(id,"asset/"+kind+"/"+reference),kind,reference,text(name,96));c.assets.put(asset.id(),asset);changed(c);return asset;}
    public void removeAsset(UUID id,UUID actor,UUID asset){require(id,actor,Permission.ASSETS);if(company(id).assets.remove(asset)==null)throw new IllegalArgumentException("company_asset_missing");changed(company(id));}
    /** Reference is an existing Cargo order; its own escrow, receipt and cancellation remain authoritative. */
    public Contract contract(UUID id,UUID actor,ContractKind kind,OwnerRef counterparty,UUID reference,long amount,int quantity,String terms,long expires,long now){require(id,actor,Permission.TRADE);money(amount,true);if(kind==ContractKind.EMPLOYMENT||quantity<0||expires<=now||expires>now+30*DAY)throw new IllegalArgumentException("company_contract");if(contracts.values().stream().anyMatch(c->c.company().equals(id)&&c.kind()==kind&&c.reference().equals(reference)))throw new IllegalArgumentException("company_contract_exists");var contract=new Contract(UUID.randomUUID(),id,kind,counterparty,reference,amount,quantity,text(terms,256),ContractState.OFFERED,now,expires);contracts.put(contract.id(),contract);changed(company(id));return contract;}
    public void acceptContract(UUID id,long now){var c=Optional.ofNullable(contracts.get(id)).orElseThrow();if(c.state()!=ContractState.OFFERED||c.expires()<now)throw new IllegalArgumentException("company_contract_expired");contracts.put(id,with(c,ContractState.ACCEPTED));changed(company(c.company()));}
    public void completeContract(UUID id){var c=Optional.ofNullable(contracts.get(id)).orElseThrow();if(c.state()==ContractState.COMPLETED)return;if(c.state()!=ContractState.ACCEPTED||c.kind()==ContractKind.EMPLOYMENT)throw new IllegalArgumentException("company_contract_state");contracts.put(id,with(c,ContractState.COMPLETED));changed(company(c.company()));}
    public void cancelContract(UUID id,UUID actor){var c=Optional.ofNullable(contracts.get(id)).orElseThrow();require(c.company(),actor,Permission.TRADE);if(c.state()!=ContractState.OFFERED)throw new IllegalArgumentException("company_contract_committed");contracts.put(id,with(c,ContractState.CANCELLED));changed(company(c.company()));}
    private static Contract with(Contract c,ContractState state){return new Contract(c.id(),c.company(),c.kind(),c.counterparty(),c.reference(),c.amount(),c.quantity(),c.terms(),state,c.created(),c.expires());}
    public ShareOffer offerShares(UUID id,UUID seller,UUID buyer,int units,long price,long now,long expires){var c=company(id);money(price,true);if(seller.equals(buyer)||units<1||expires<=now||expires>now+30*DAY)throw new IllegalArgumentException("company_share_offer");int locked=shareOffers.values().stream().filter(o->o.company().equals(id)&&o.seller().equals(seller)&&!o.closed()&&o.expires()>now).mapToInt(ShareOffer::units).sum();if((long)locked+units>c.shares.getOrDefault(seller,0))throw new IllegalArgumentException("company_shares_locked");var o=new ShareOffer(UUID.randomUUID(),id,seller,buyer,units,price,expires,false,c.totalShares(),c.charter,c.city,tax(c.city).version());shareOffers.put(o.id(),o);changed(c);return o;}
    public void acceptShares(UUID offerId,UUID actor,long now){var o=Optional.ofNullable(shareOffers.get(offerId)).orElseThrow();var c=company(o.company());if(o.closed()||!o.buyer().equals(actor)||o.expires()<now||c.shares.getOrDefault(o.seller(),0)<o.units())throw new IllegalArgumentException("company_share_offer_expired");if(o.capital()!=c.totalShares()||!o.charter().equals(c.charter)||!o.city().equals(c.city)||o.taxVersion()!=tax(c.city).version())throw new IllegalArgumentException("company_share_terms_changed");int buyerShares=Math.addExact(c.shares.getOrDefault(actor,0),o.units());transfer(OwnerRef.player(actor),OwnerRef.player(o.seller()),o.price());putShares(c,o.seller(),c.shares.get(o.seller())-o.units());putShares(c,actor,buyerShares);shareOffers.put(o.id(),closed(o));changed(c);}
    public void cancelShares(UUID offer,UUID actor){var o=Optional.ofNullable(shareOffers.get(offer)).orElseThrow();if(!o.seller().equals(actor))throw new IllegalArgumentException("company_permission");shareOffers.put(o.id(),closed(o));changed(company(o.company()));}
    private static ShareOffer closed(ShareOffer o){return new ShareOffer(o.id(),o.company(),o.seller(),o.buyer(),o.units(),o.price(),o.expires(),true,o.capital(),o.charter(),o.city(),o.taxVersion());}
    private static void putShares(Company c,UUID actor,int units){if(units==0)c.shares.remove(actor);else c.shares.put(actor,units);}
    public Vote propose(UUID id,UUID actor,Decision decision,UUID target,long amount,String text,long now){var c=company(id);if(!shareholder(id,actor))throw new IllegalArgumentException("company_shareholder");if(amount<0||amount>accounts.maximum()||text.length()>256)throw new IllegalArgumentException("company_proposal");if(decision==Decision.ISSUE_SHARES&&(amount<1||amount>1_000_000_000L-c.totalShares()))throw new IllegalArgumentException("company_share_limit");var vote=new Vote(UUID.randomUUID(),id,decision,target,amount,text,c.shares,Map.of(),now+7*DAY,"OPEN");votes.put(vote.id(),vote);changed(c);return vote;}
    public void vote(UUID proposal,UUID actor,boolean yes,long now){var v=Optional.ofNullable(votes.get(proposal)).orElseThrow();if(!v.state().equals("OPEN")||v.expires()<now||!v.electorate().containsKey(actor)||v.ballots().containsKey(actor))throw new IllegalArgumentException("company_vote");var ballots=new HashMap<>(v.ballots());ballots.put(actor,yes);v=new Vote(v.id(),v.company(),v.decision(),v.target(),v.amount(),v.text(),v.electorate(),ballots,v.expires(),"OPEN");votes.put(v.id(),v);changed(company(v.company()));if(v.yes()>v.total()/2)executeVote(v,now);}
    public void executeApproved(UUID id,long now){var v=Optional.ofNullable(votes.get(id)).orElseThrow();if(!v.state().equals("OPEN")||v.expires()<now||v.yes()<=v.total()/2)throw new IllegalArgumentException("company_vote");executeVote(v,now);}
    private void executeVote(Vote v,long now){var c=company(v.company());switch(v.decision()){
        case DIRECTOR -> {Objects.requireNonNull(v.target());if(Boolean.TRUE.equals(v.ballots().get(v.target())))appointDirector(c,v.target(),now,v.id());else{supercedeAppointments(c,v.id());var employee=c.employees.get(v.target());var invitation=new Invite(stable(v.id(),"director-acceptance"),c.id,v.target(),Role.DIRECTOR,employee!=null&&employee.active()?employee.salary():0,now+7*DAY,false,v.id());invites.put(invitation.id(),invitation);c.pendingDirector=v.id();votes.put(v.id(),voteState(v,"AWAITING_ACCEPTANCE"));changed(c);return;}}
        case CITY -> c.city=Objects.requireNonNull(v.target());
        case CHARTER -> c.charter=v.text();
        case ISSUE_SHARES -> {int units=Math.toIntExact(v.amount());if((long)c.totalShares()+units>1_000_000_000L)throw new IllegalArgumentException("company_share_limit");putShares(c,v.target(),Math.addExact(c.shares.getOrDefault(v.target(),0),units));}
        case DIVIDEND -> dividend(c,v.amount(),now);
        case ARCHIVE -> {accrue(c,now);if(accounts.balance(owner(c.id))!=0||c.salaryDebt()!=0||externalDebt.applyAsLong(owner(c.id))>0||!c.assets.isEmpty()||c.employees.values().stream().anyMatch(e->e.active()&&e.salary()>0)||contracts.values().stream().anyMatch(k->k.company().equals(c.id)&&k.state()==ContractState.ACCEPTED&&k.kind()!=ContractKind.EMPLOYMENT))throw new IllegalArgumentException("company_obligations");supercedeAppointments(c,null);c.pendingDirector=null;invites.values().removeIf(i->i.company().equals(c.id));c.archived=true;}
        }votes.put(v.id(),new Vote(v.id(),v.company(),v.decision(),v.target(),v.amount(),v.text(),v.electorate(),v.ballots(),v.expires(),"EXECUTED"));changed(c);}
    private static Vote voteState(Vote v,String state){return new Vote(v.id(),v.company(),v.decision(),v.target(),v.amount(),v.text(),v.electorate(),v.ballots(),v.expires(),state);}
    private void supercedeAppointments(Company c,UUID keep){for(var old:List.copyOf(votes.values()))if(old.company().equals(c.id)&&old.state().equals("AWAITING_ACCEPTANCE")&&!old.id().equals(keep))votes.put(old.id(),voteState(old,"SUPERSEDED"));invites.values().removeIf(i->i.company().equals(c.id)&&i.appointment()!=null&&!i.appointment().equals(keep));}
    private void appointDirector(Company c,UUID target,long now,UUID decision){accrue(c,now);supercedeAppointments(c,decision);for(var old:List.copyOf(c.employees.values()))if(old.active()&&old.role()==Role.DIRECTOR)c.employees.put(old.player(),new Employee(old.player(),Role.MANAGER,old.salary(),old.started(),old.accruedUntil(),old.ended(),old.remainder(),old.arrears(),old.firstUnpaid()));var employee=c.employees.get(target);if(employee!=null&&employee.active())c.employees.put(target,new Employee(target,Role.DIRECTOR,employee.salary(),employee.started(),employee.accruedUntil(),0,employee.remainder(),employee.arrears(),employee.firstUnpaid()));else c.employees.put(target,new Employee(target,Role.DIRECTOR,0,now,employee==null?now:Math.max(now,employee.accruedUntil()),0,employee==null?0:employee.remainder(),employee==null?0:employee.arrears(),employee==null?0:employee.firstUnpaid()));c.pendingDirector=null;}
    private void dividend(Company c,long amount,long now){money(amount,false);if(amount>distributable(c.id,now))throw new IllegalArgumentException("company_obligations");var ordered=c.shares.entrySet().stream().sorted(Comparator.<Map.Entry<UUID,Integer>>comparingInt(Map.Entry::getValue).reversed().thenComparing(e->e.getKey().toString())).toList();long total=c.totalShares(),paid=0;var credits=new LinkedHashMap<OwnerRef,Long>();for(var share:ordered){long n=BigInteger.valueOf(amount).multiply(BigInteger.valueOf(share.getValue())).divide(BigInteger.valueOf(total)).longValueExact();credits.put(OwnerRef.player(share.getKey()),n);paid=Math.addExact(paid,n);}credits.merge(OwnerRef.player(ordered.getFirst().getKey()),amount-paid,Math::addExact);for(var e:credits.entrySet())if(!accounts.canCredit(e.getKey(),e.getValue()))throw new IllegalArgumentException("company_credit");if(!accounts.debit(owner(c.id),amount))throw new IllegalArgumentException("company_funds");credits.forEach(accounts::credit);accounts.dirty();}
    public boolean commandDone(UUID id,String fingerprint){String old=commands.get(id);if(old==null)return false;if(!old.equals(fingerprint))throw new IllegalArgumentException("company_request_conflict");return true;}
    public void commandCompleted(UUID id,String fingerprint){commands.put(id,fingerprint);accounts.dirty();}
    public static UUID stable(UUID company,String key){return UUID.nameUUIDFromBytes((company+"/"+key).getBytes(java.nio.charset.StandardCharsets.UTF_8));}

    public CompoundTag save(){
        var root=new CompoundTag();root.putInt("Version",1);var list=new ListTag();for(var c:companies.values()){var t=new CompoundTag();t.putUUID("Id",c.id);t.putUUID("Founder",c.founder);t.putUUID("City",c.city);if(c.pendingDirector!=null)t.putUUID("PendingDirector",c.pendingDirector);t.putString("Name",c.name);t.putString("Charter",c.charter);t.putBoolean("Archived",c.archived);t.putLong("Revision",c.revision);t.putLong("Revenue",c.revenue);t.putLong("TaxPaid",c.taxPaid);t.putLong("TaxRemainder",c.taxRemainder);t.putLong("SalaryPaid",c.salaryPaid);var staff=new ListTag();for(var e:c.employees.values()){var n=new CompoundTag();n.putUUID("Player",e.player());n.putString("Role",e.role().name());n.putLong("Salary",e.salary());n.putLong("Started",e.started());n.putLong("AccruedUntil",e.accruedUntil());n.putLong("Ended",e.ended());n.putLong("Remainder",e.remainder());n.putLong("Arrears",e.arrears());n.putLong("FirstUnpaid",e.firstUnpaid());staff.add(n);}t.put("Employees",staff);t.put("Shares",writeWeights(c.shares));var assets=new ListTag();for(var a:c.assets.values()){var n=new CompoundTag();n.putUUID("Id",a.id());n.putString("Kind",a.kind().name());n.putUUID("Reference",a.reference());n.putString("Name",a.name());assets.add(n);}t.put("Assets",assets);list.add(t);}root.put("Companies",list);
        var invitationList=new ListTag();for(var i:invites.values()){var t=identity(i.id(),i.company());t.putUUID("Player",i.player());t.putString("Role",i.role().name());t.putLong("Salary",i.salary());t.putLong("Expires",i.expires());t.putBoolean("Amendment",i.amendment());if(i.appointment()!=null)t.putUUID("Appointment",i.appointment());invitationList.add(t);}root.put("Invites",invitationList);
        var contractList=new ListTag();for(var c:contracts.values()){var t=identity(c.id(),c.company());t.putString("Kind",c.kind().name());t.put("Counterparty",c.counterparty().save());t.putUUID("Reference",c.reference());t.putLong("Amount",c.amount());t.putInt("Quantity",c.quantity());t.putString("Terms",c.terms());t.putString("State",c.state().name());t.putLong("Created",c.created());t.putLong("Expires",c.expires());contractList.add(t);}root.put("Contracts",contractList);
        var offers=new ListTag();for(var o:shareOffers.values()){var t=identity(o.id(),o.company());t.putUUID("Seller",o.seller());t.putUUID("Buyer",o.buyer());t.putInt("Units",o.units());t.putLong("Price",o.price());t.putLong("Expires",o.expires());t.putBoolean("Closed",o.closed());t.putInt("Capital",o.capital());t.putString("Charter",o.charter());t.putUUID("City",o.city());t.putLong("TaxVersion",o.taxVersion());offers.add(t);}root.put("ShareOffers",offers);
        var proposals=new ListTag();for(var v:votes.values()){var t=identity(v.id(),v.company());t.putString("Decision",v.decision().name());if(v.target()!=null)t.putUUID("Target",v.target());t.putLong("Amount",v.amount());t.putString("Text",v.text());t.put("Electorate",writeWeights(v.electorate()));var ballots=new ListTag();v.ballots().forEach((player,yes)->{var n=new CompoundTag();n.putUUID("Player",player);n.putBoolean("Yes",yes);ballots.add(n);});t.put("Ballots",ballots);t.putLong("Expires",v.expires());t.putString("State",v.state());proposals.add(t);}root.put("Votes",proposals);
        var policy=new ListTag();taxes.forEach((city,p)->{var t=new CompoundTag();t.putUUID("City",city);t.putInt("Rate",p.basisPoints());t.putLong("Version",p.version());policy.add(t);});root.put("Taxes",policy);
        var revenue=new ListTag();for(var r:receipts.values()){var t=identity(r.receipt(),r.company());t.putUUID("City",r.city());t.putLong("Gross",r.gross());t.putLong("Tax",r.tax());t.putInt("Rate",r.rate());t.putLong("Policy",r.policy());t.putLong("Time",r.time());revenue.add(t);}root.put("Receipts",revenue);
        var requests=new ListTag();commands.forEach((id,value)->{var t=new CompoundTag();t.putUUID("Id",id);t.putString("Fingerprint",value);requests.add(t);});root.put("Commands",requests);return root;
    }
    private static CompoundTag identity(UUID id,UUID company){var t=new CompoundTag();t.putUUID("Id",id);t.putUUID("Company",company);return t;}
    private static ListTag writeWeights(Map<UUID,Integer> weights){var list=new ListTag();weights.forEach((player,units)->{var t=new CompoundTag();t.putUUID("Player",player);t.putInt("Units",units);list.add(t);});return list;}
    private static Map<UUID,Integer> weights(ListTag list){var result=new LinkedHashMap<UUID,Integer>();long total=0;for(Tag raw:list){var t=(CompoundTag)raw;int units=t.getInt("Units");if(units<1||result.putIfAbsent(t.getUUID("Player"),units)!=null)throw new IllegalArgumentException("company_invalid_shares");total+=units;if(total>1_000_000_000L)throw new IllegalArgumentException("company_invalid_shares");}return result;}
    private static <T> void unique(Map<UUID,T> map,UUID id,T value){if(map.putIfAbsent(id,value)!=null)throw new IllegalArgumentException("company_duplicate");}
    public void load(CompoundTag root){if(root.isEmpty())return;if(root.getInt("Version")!=1)throw new IllegalArgumentException("company_version");companies.clear();invites.clear();contracts.clear();shareOffers.clear();votes.clear();taxes.clear();receipts.clear();commands.clear();
        for(Tag raw:root.getList("Companies",10)){var t=(CompoundTag)raw;var c=new Company(t.getUUID("Id"),t.getUUID("Founder"),text(t.getString("Name"),64),t.getUUID("City"));c.pendingDirector=t.hasUUID("PendingDirector")?t.getUUID("PendingDirector"):null;c.charter=t.getString("Charter");c.archived=t.getBoolean("Archived");c.revision=t.getLong("Revision");c.revenue=t.getLong("Revenue");c.taxPaid=t.getLong("TaxPaid");c.taxRemainder=t.getLong("TaxRemainder");c.salaryPaid=t.getLong("SalaryPaid");if(c.revision<0||c.revenue<0||c.taxPaid<0||c.taxRemainder<0||c.taxRemainder>=10_000||c.salaryPaid<0||c.charter.length()>256)throw new IllegalArgumentException("company_invalid");for(Tag employee:t.getList("Employees",10)){var e=(CompoundTag)employee;var value=new Employee(e.getUUID("Player"),Role.valueOf(e.getString("Role")),e.getLong("Salary"),e.getLong("Started"),e.getLong("AccruedUntil"),e.getLong("Ended"),e.getLong("Remainder"),e.getLong("Arrears"),e.getLong("FirstUnpaid"));if(value.salary()<0||value.started()<0||value.accruedUntil()<value.started()||value.ended()<0||value.remainder()<0||value.remainder()>=DAY||value.arrears()<0||value.firstUnpaid()<0)throw new IllegalArgumentException("company_employee_invalid");unique(c.employees,value.player(),value);}c.shares.putAll(weights(t.getList("Shares",10)));if(c.shares.isEmpty())throw new IllegalArgumentException("company_missing_shares");for(Tag asset:t.getList("Assets",10)){var a=(CompoundTag)asset;var value=new Asset(a.getUUID("Id"),AssetKind.valueOf(a.getString("Kind")),a.getUUID("Reference"),text(a.getString("Name"),96));unique(c.assets,value.id(),value);}unique(companies,c.id,c);}
        for(Tag raw:root.getList("Invites",10)){var t=(CompoundTag)raw;var i=new Invite(t.getUUID("Id"),t.getUUID("Company"),t.getUUID("Player"),Role.valueOf(t.getString("Role")),t.getLong("Salary"),t.getLong("Expires"),t.getBoolean("Amendment"),t.hasUUID("Appointment")?t.getUUID("Appointment"):null);if(i.salary()<0||i.expires()<0||!companies.containsKey(i.company())||i.appointment()!=null&&i.role()!=Role.DIRECTOR||i.role()==Role.DIRECTOR&&i.appointment()==null&&!i.amendment())throw new IllegalArgumentException("company_invite_invalid");unique(invites,i.id(),i);}
        for(Tag raw:root.getList("Contracts",10)){var t=(CompoundTag)raw;var c=new Contract(t.getUUID("Id"),t.getUUID("Company"),ContractKind.valueOf(t.getString("Kind")),OwnerRef.load(t.getCompound("Counterparty")),t.getUUID("Reference"),t.getLong("Amount"),t.getInt("Quantity"),t.getString("Terms"),ContractState.valueOf(t.getString("State")),t.getLong("Created"),t.getLong("Expires"));if(!companies.containsKey(c.company())||c.amount()<0||c.quantity()<0||c.created()<0||c.expires()<c.created()||c.terms().length()>256)throw new IllegalArgumentException("company_contract_invalid");unique(contracts,c.id(),c);}
        for(Tag raw:root.getList("ShareOffers",10)){var t=(CompoundTag)raw;var o=new ShareOffer(t.getUUID("Id"),t.getUUID("Company"),t.getUUID("Seller"),t.getUUID("Buyer"),t.getInt("Units"),t.getLong("Price"),t.getLong("Expires"),t.getBoolean("Closed"),t.getInt("Capital"),t.getString("Charter"),t.getUUID("City"),t.getLong("TaxVersion"));if(!companies.containsKey(o.company())||o.units()<1||o.price()<0||o.expires()<0||o.capital()<1||o.units()>o.capital()||o.charter().length()>256||o.taxVersion()<0)throw new IllegalArgumentException("company_share_offer_invalid");unique(shareOffers,o.id(),o);}
        for(Tag raw:root.getList("Votes",10)){var t=(CompoundTag)raw;var ballots=new LinkedHashMap<UUID,Boolean>();for(Tag rawBallot:t.getList("Ballots",10)){var b=(CompoundTag)rawBallot;unique(ballots,b.getUUID("Player"),b.getBoolean("Yes"));}var electorate=weights(t.getList("Electorate",10));var v=new Vote(t.getUUID("Id"),t.getUUID("Company"),Decision.valueOf(t.getString("Decision")),t.hasUUID("Target")?t.getUUID("Target"):null,t.getLong("Amount"),t.getString("Text"),electorate,ballots,t.getLong("Expires"),t.getString("State"));if(!companies.containsKey(v.company())||v.amount()<0||v.expires()<0||!Set.of("OPEN","EXECUTED","AWAITING_ACCEPTANCE","SUPERSEDED","DECLINED").contains(v.state())||!electorate.keySet().containsAll(ballots.keySet()))throw new IllegalArgumentException("company_vote_invalid");unique(votes,v.id(),v);}
        for(var c:companies.values())if(c.pendingDirector!=null){var v=votes.get(c.pendingDirector);if(v==null||v.decision()!=Decision.DIRECTOR||!v.company().equals(c.id)||!v.state().equals("AWAITING_ACCEPTANCE")||invites.values().stream().noneMatch(i->c.pendingDirector.equals(i.appointment())&&i.company().equals(c.id)&&i.player().equals(v.target())))throw new IllegalArgumentException("company_appointment_invalid");}
        for(Tag raw:root.getList("Taxes",10)){var t=(CompoundTag)raw;var p=new TaxPolicy(t.getInt("Rate"),t.getLong("Version"));if(p.basisPoints()<0||p.basisPoints()>10_000||p.version()<0)throw new IllegalArgumentException("company_tax_invalid");unique(taxes,t.getUUID("City"),p);}
        for(Tag raw:root.getList("Receipts",10)){var t=(CompoundTag)raw;var r=new Revenue(t.getUUID("Id"),t.getUUID("Company"),t.getUUID("City"),t.getLong("Gross"),t.getLong("Tax"),t.getInt("Rate"),t.getLong("Policy"),t.getLong("Time"));if(!companies.containsKey(r.company())||r.gross()<0||r.tax()<0||r.tax()>r.gross()||r.rate()<0||r.rate()>10_000)throw new IllegalArgumentException("company_revenue_invalid");unique(receipts,r.receipt(),r);}
        for(Tag raw:root.getList("Commands",10)){var t=(CompoundTag)raw;unique(commands,t.getUUID("Id"),t.getString("Fingerprint"));}
    }
}
